INSERT INTO `chat_messages` VALUES (1,1,'user','I have weak nails, what do you recommend?',NULL,'2026-09-23 07:27:09.284'),(2,1,'bot','For clients looking to improve the condition of their nails, we offer several services that can help strengthen and protect them. \n\nWe recommend starting with our Signature Manicure (No Polish) to clean and groom your nails, or our Soft BIAB (Full Set), which is a popular treatment for strengthening natural nails. \n\nIf you are a new client, I highly recommend our Consultation First service (₱0, 15 minutes). This allows our professionals to assess your nail health and provide a personalized plan to help them grow stronger and healthier.\n\nYou can view our full list of nail care services, including various spa treatments and extensions, in our menu. Please let me know if you would like to book an appointment!\n\nPlease consult with our clinic professionals for personalized advice.',NULL,'2026-09-23 07:27:13.457');
